import { STATUS_CODES } from 'node:http'

// An error whose message is safe to show to API clients.
export class HttpError extends Error {
  constructor(status, code, message) {
    super(message)
    this.name = 'HttpError'
    this.status = status
    this.code = code
  }
}

export function notFoundHandler(req, res, next) {
  next(new HttpError(404, 'not_found', 'Route not found'))
}

// Turns any error into the public JSON error shape. Internal details are logged, never sent.
export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err)

  const { status, code, message } = toClientError(err)

  if (status >= 500) {
    console.error(`${req.method} ${req.originalUrl} failed:`, err)
  }

  res.status(status).json({ error: { code, message } })
}

function toClientError(err) {
  if (err instanceof HttpError) {
    return { status: err.status, code: err.code, message: err.message }
  }

  // Errors from express.json (body-parser).
  if (err?.type === 'entity.parse.failed') {
    return { status: 400, code: 'invalid_json', message: 'Request body is not valid JSON' }
  }
  if (err?.type === 'entity.too.large') {
    return { status: 413, code: 'payload_too_large', message: 'Request body must be 10kb or smaller' }
  }

  // Other errors that are explicitly client-facing (e.g. unsupported charset, malformed URL params).
  if (Number.isInteger(err?.status) && err.status >= 400 && err.status < 500 && err.expose) {
    const code = err.status === 415 ? 'unsupported_media_type' : 'bad_request'
    return { status: err.status, code, message: STATUS_CODES[err.status] ?? 'Bad request' }
  }

  return { status: 500, code: 'internal_error', message: 'An unexpected error occurred' }
}

