// Body is undefined when the request has no JSON body; treat that as an empty object.
function validateNewOrder(body = {}) {
  const input = body !== null && typeof body === 'object' ? body : {}
  const problems = []

  const { sku, quantity } = input
  if (typeof sku !== 'string' || sku.trim() === '') {
    problems.push('sku must be a non-empty string')
  }
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > 100) {
    problems.push('quantity must be an integer from 1 to 100')
  }

  if (problems.length > 0) {
    throw new HttpError(400, 'validation_failed', problems.join('; '))
  }
  return { sku, quantity }
}

